package br.com.sussmartcare.identityaccess.domain; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="communication_profiles") public class CommunicationProfile { @Id private UUID userId; @Column(nullable=false) private boolean hasSmartphone; @Column(nullable=false) private String preferredChannel; protected CommunicationProfile(){} public CommunicationProfile(UUID userId,boolean hasSmartphone,String preferredChannel){this.userId=userId;this.hasSmartphone=hasSmartphone;this.preferredChannel=preferredChannel;} public UUID getUserId(){return userId;} public boolean isHasSmartphone(){return hasSmartphone;} public String getPreferredChannel(){return preferredChannel;} }